 private var inputs:[(String,String)] {[("fact",factRaw),("prescribed",prescribedRaw),("coreFact",factRaw),("corePrescription",prescriptionRaw),("bundle",bundleRaw)]}
 private func roundTrip(_ name:String,_ data:Data) throws -> Data {
  let decoder=CodableHelper.jsonDecoder,encoder=CodableHelper.jsonEncoder
  switch name {
  case "fact":return try encoder.encode(decoder.decode(SetExecutionSyncView.self,from:data))
  case "prescribed":return try encoder.encode(decoder.decode(PrescribedSetSyncView.self,from:data))
  case "coreFact","corePrescription","unknown":return try encoder.encode(decoder.decode(WorkoutCoreSyncView.self,from:data))
  default:return try encoder.encode(decoder.decode(OfflineWorkoutBundle.self,from:data))
  }
 }
 private func halfLoads(_ data:Data) throws -> Int {
  // This control uses exactly representable 0.5 only; precision negatives enter
  // through the public SDK decoder, never a test-only numeric helper.
  func count(_ value:Any)->Int {
   if let fields=value as? [String:Any] {
    let own=(fields["loadValue"] as? NSNumber).map { $0.doubleValue==0.5 ? 1:0 } ?? 0
    return own+fields.values.reduce(0) { $0+count($1) }
   }
   if let values=value as? [Any] {return values.reduce(0) { $0+count($1) }}
   return 0
  }
  return count(try JSONSerialization.jsonObject(with:data))
 }
 func testRepresentableValuesSurviveLeafUnionAndBundle() throws {
  let expected=["fact":2,"prescribed":1,"coreFact":2,"corePrescription":1,"bundle":3]
  for (name,template) in inputs {
   let data=Data(template.replacingOccurrences(of:"C10_NUMBER_TOKEN",with:"0.5").utf8)
   let encoded=try roundTrip(name,data)
   XCTAssertEqual(try halfLoads(encoded),expected[name]!,name)
   XCTAssertNoThrow(try roundTrip(name,encoded),name)
  }
 }
 func testNonrepresentableValuesAreExplicitlyRefusedInEveryEnvelope() {
  for literal in ["1.0000000000000001","12345678901234567890.1234567890123456789","1e-400"] {
   for (name,template) in inputs {
    let data=Data(template.replacingOccurrences(of:"C10_NUMBER_TOKEN",with:literal).utf8)
    XCTAssertThrowsError(try roundTrip(name,data),name+" "+literal) { error in
     guard case DecodingError.dataCorrupted(let context)=error else {return XCTFail("Expected explicit native representation refusal")}
     XCTAssertTrue(context.debugDescription.contains("not losslessly representable"),name+": "+context.debugDescription)
    }
   }
  }
 }
 func testUnknownBundleViewRemainsAnOpenResponse() throws {
  let data=Data(#"{"viewType":"FUTURE_FACT","future":"preserved"}"#.utf8)
  let encoded=try roundTrip("unknown",data)
  let fields=try JSONSerialization.jsonObject(with:encoded) as! [String:Any]
  XCTAssertEqual(fields["viewType"] as? String,"FUTURE_FACT")
  XCTAssertEqual(fields["future"] as? String,"preserved")
 }
